__NUXT_JSONP__("/ch/how-to-apply/student-visa-f1/transfer-students", {data:[{details:{slug:"ch",pageTitle:"转学生 | Mentor Language Institute",pageDescription:"目前就读于在美国的学校，想要转学的学生 ",title:"转学生",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Ftransfer-students.jpg",section:[{description:["目前就读于在美国的学校，想要转学的学生"]}],category:[{image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-steps-ch.png",listType:"decimal",lists:["向 MLI申请(填写在线表格)","提交有效文件","参加新生迎新会","接收新的I-20"],description:["学生必须在上课日期的一至两个月前向MLI申请。提交在线申请表格后，最好能够跟MLI学生咨询师确认转学状态，因为依据每个人的情况有时候过程可能会较复杂。"],hasApplyNow:true},{title:"取消细则",description:["注册费$150需申请时付款，无论签证被拒绝或是注册被取消都不可退还。"]},{title:"申请后",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-form-en.jpg",description:["学生提交在线申请表后，MLI会审核申请表并将申请表网址传给iMLI。学生可以透过iMLI追踪申请状况。"]}],applyOnline:{title:"在线申請",description:["请填写在线申请表格。如有任何疑问请通过邮箱联系我们。"],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapply-now-ch.png",link:"\u002Fch\u002Fadmission"}},dir:"\u002Ftransfer-students",path:"\u002Ftransfer-students\u002Fch",extension:".json",createdAt:"2026-10-22T16:31:31.272Z",updatedAt:"2025-05-26T12:06:27.944Z"}}],fetch:{},mutations:void 0});